// TH16 v1.00a approved aliases of identical TH18 type 0..43 slots (2026-11-07).
// Copied from transcribe/th16/touhou-bullets.ecl; only the types this card uses.
const TH16_TALISMAN: int = 528;   // source type 11: EX record 512 SETSPRITE
const TH16_ARROWHEAD: int = 544;  // source type 12: BossCard3B_at initial sprite
const TH16_STAR_R: int = 608;     // source type 16: BossCard3_at initial sprite

// TH16 v1.00a st05bs.ecl.txt BossCard3 / BossCard3B — 舞符「ビハインドフェスティバル」
// Parallel two-boss spell: Boss(+64) runs BossCard3p/BossCard3_at, BossB(-64) runs
// BossCard3Bp/BossCard3B_at. The source reaches each boss's wrapper once via
// enmCall($GI1/$GI0); here each spawned boss runs its own wrapper directly.
// Source frames: wrapper intro `+120:` plus a 3000-frame setInterrupt window.
// Card frames = source frames + OPENING_BUFFER (shell); see report.md.

const TIME_LIMIT: int = 3124;
const OPENING_BUFFER: int = 120;
const SOURCE_INTRO: int = 120;      // source wrapper's own `+120:` gate

// ---------------------------------------------------------------------------
// Source BossCard3_at EX program (records 1..12): six (STEP, ANGLE_ACCEL) pairs.
// STEP a=B(60..119) b=1 c=0 -> linear decel to 0 over a, then angle += r and the
// entry speed is kept (s=-999999). ANGLE_ACCEL a=B r=0 s=+-0.008726646rad (0.5deg).
// Each pair shares one B. Encoded as: decel + spin over the same d frames, then
// turn r and restore speed; the spin sign alternates per pair and the source
// alternates the whole pattern per shot (MAIN_A / MAIN_B).
// ---------------------------------------------------------------------------
xformdef MAIN_A(d1: int, d2: int, spd: fx) {
again:
    step_speed(0fx, d1 + 65536 * EASE_LINEAR);
    set_ang_vel(0.5deg);
    wait(d1);
    turn(-30deg);
    set_speed(spd);
    step_speed(0fx, d2 + 65536 * EASE_LINEAR);
    set_ang_vel(-0.5deg);
    wait(d2);
    turn(30deg);
    set_speed(spd);
    loop(again, 3);
    set_ang_vel(0deg);
}

xformdef MAIN_B(d1: int, d2: int, spd: fx) {
again:
    step_speed(0fx, d1 + 65536 * EASE_LINEAR);
    set_ang_vel(-0.5deg);
    wait(d1);
    turn(30deg);
    set_speed(spd);
    step_speed(0fx, d2 + 65536 * EASE_LINEAR);
    set_ang_vel(0.5deg);
    wait(d2);
    turn(-30deg);
    set_speed(spd);
    loop(again, 3);
    set_ang_vel(0deg);
}

// Source BossCard3B_at EX program:
//   record 2   ACCEL a=120 r=0.01 s=-999999  (fixed direction = entry angle 90deg)
//   record 64  BOUNCE a=1 b=2(=D) r=1.0      (one bottom-wall bounce)
//   record 512 SETSPRITE 11 / color 4        (+0x8000 ANM interrupt, visual only)
//   record 16  STEP a=1 b=1 c=1 d=0 r=0 s=tgt (segment boundary: re-aim at player)
xformdef B_PROG(tgt: fx) {
    @120 set_gravity(0fx, 0.01fx);
    stop_fx();
    bounce_arm(8, 1);
    set_sprite(TH16_TALISMAN, 4);
    wait(1);
    aim_player(0deg);
    set_speed(tgt);
}

// ---------------------------------------------------------------------------
// moveRand(120, 0, 0.4) with moveLimit(cx, 128, 240, 64); recipe (per-frame
// clamped step, speed decays 0.4 -> 0 over 120 frames) from movement.md.
// Enemy slots: int0 = next step index, fx0/fx1 = logical cos/sin.
// ---------------------------------------------------------------------------
sub card_step(cx: fx) {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 120 { speed = 0.4fx * ((120 - k) as fx) / 120fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < cx - 120fx { nx = cx - 120fx; }
    if nx > cx + 120fx { nx = cx + 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(cx: fx, a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_step(cx);
}

sub card_wait(cx: fx, frames: int) {
    for i in 0..frames {
        wait(1);
        card_step(cx);
    }
}

sub card_move_rand(cx: fx) {
    // Signed unit random as unwrapped BAM ints (source 405b90 = signed * pi).
    var r: int = rand(65536) - 32768;
    var a: int = 0;
    if $self_x < cx - 60fx {
        a = r / 3;
    } else if $self_x > cx + 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(cx, a as angle);
}

// ---------------------------------------------------------------------------
// BossCard3_at: stream from the top edge, one bullet per shot, base angle
// +90deg, two alternating EX programs per loop iteration.
// ---------------------------------------------------------------------------
async sub fire_main() {
    var gap: int = 12;          // !E 12 / !N 10 / !H 7 / !LO 6
    var spd: fx = 1.5fx;        // !E 1.5 / !N 2.0 / !H 2.0 / !LO 2.0
    var rank: int = global(GVAR_RANK);
    if rank == RANK_NORMAL { gap = 10; spd = 2fx; }
    if rank == RANK_HARD { gap = 7; spd = 2fx; }
    if rank == RANK_LUNATIC { gap = 6; spd = 2fx; }

    sh_reset(0);
    sh_sprite(0, TH16_STAR_R, 6);       // etSprite(0, 16, 6)
    sh_ring(0, 1);                      // etAim(0, 3): fixed-direction ring
    sh_aim(0, 0);
    sh_count(0, 1, 1);                  // etCount(0, 1, 1)
    sh_angle(0, 90deg, 0deg);           // etAngle(0, +pi/2, 0)
    sh_speed(0, spd, 0fx);              // etSpeed(0, s0, 1.2) with M=1 -> s0

    loop {
        var u: int = rand(65536) - 32768;
        var sx: fx = (u as fx) / 32768;
        sh_xform(0, MAIN_A(rand(60) + 60, rand(60) + 60, spd));
        sh_offset_abs(0, (0fx - 192fx) * sx, 0fx);   // RANDF2 * -192, y=0
        sh_fire(0);
        wait(gap);
        u = rand(65536) - 32768;
        sx = (u as fx) / 32768;
        sh_xform(0, MAIN_B(rand(60) + 60, rand(60) + 60, spd));
        sh_offset_abs(0, (0fx - 192fx) * sx, 0fx);
        sh_fire(0);
        wait(gap);
    }
}

// ---------------------------------------------------------------------------
// BossCard3B_at: four-shot cycle (17 frames apart), one random x per shot.
// ---------------------------------------------------------------------------
async sub fire_b() {
    var spd0: fx = 1.5fx;       // !E 1.5 / !N 2.0 / !H 2.3 / !LO 2.5
    var step: fx = 0fx;         // last-layer speed delta
    var layers: int = 1;        // !E 1 / !N 1 / !H 2 / !LO 2
    var tgt: fx = 1fx;          // STEP s: !E/N/H 1.0 / !LO 1.5
    var rank: int = global(GVAR_RANK);
    if rank == RANK_NORMAL { spd0 = 2fx; }
    if rank == RANK_HARD { spd0 = 2.3fx; step = -0.3fx; layers = 2; }
    if rank == RANK_LUNATIC { spd0 = 2.5fx; step = -0.7fx; layers = 2; tgt = 1.5fx; }

    sh_reset(0);
    sh_sprite(0, TH16_ARROWHEAD, 6);    // etSprite(0, 12, 6)
    sh_ring(0, 1);                      // etAim(0, 3)
    sh_aim(0, 0);
    sh_count(0, 1, layers);             // etCount(0, 1, 1/1/2/2)
    sh_angle(0, 90deg, 0deg);           // etAngle(0, +pi/2, 0)
    sh_speed(0, spd0, step);            // etSpeed(0, s0, 1.8)
    sh_xform(0, B_PROG(tgt));

    loop {
        var u: int = rand(65536) - 32768;
        var sx: fx = (u as fx) / 32768;
        sh_offset_abs(0, 192fx * sx, 0fx);              // RANDF2 * 192
        sh_fire(0);
        wait(17);
        u = rand(65536) - 32768;
        sx = (u as fx) / 32768;
        sh_offset_abs(0, 64fx * sx - 128fx, 0fx);       // RANDF2 * 64 - 128
        sh_fire(0);
        wait(17);
        u = rand(65536) - 32768;
        sx = (u as fx) / 32768;
        sh_offset_abs(0, 64fx * sx + 128fx, 0fx);       // RANDF2 * 64 + 128
        sh_fire(0);
        wait(17);
        u = rand(65536) - 32768;
        sx = (u as fx) / 32768;
        sh_offset_abs(0, 64fx * sx, 0fx);               // RANDF2 * 64
        sh_fire(0);
        wait(17);
    }
}

// ---------------------------------------------------------------------------
// BossCard3p / BossCard3Bp wrappers (source 2382-2434 / 2238-2290).
// Omitted here: lifeNow/spellMode/setInvuln(10)/timerReset/killAllAsync/
// enmKillAll/etCancel/funcSet(0)/laserCancel/playSound/anm*/dropSeason and
// unknown543 — outside attack content per transcription-policy, or the
// standalone shell starts clean with no prior tasks/lasers/callbacks.
// ---------------------------------------------------------------------------
async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx);                     // setHurtbox(40, 40) -> r=20
    set_hitbox(24fx);                      // setHitbox(48, 48) -> r=24
    move_to(60, 64fx, 128fx, EASE_QUAD_OUT);   // movePosTime(60, 4, 64, 128)
    wait(SOURCE_INTRO);
    spawn fire_main();
    loop {
        card_wait(64fx, 160);
        card_move_rand(64fx);
        card_wait(64fx, 160);
    }
}

async sub boss_b_main() {
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    move_to(60, -64fx, 128fx, EASE_QUAD_OUT);  // movePosTime(60, 4, -64, 128)
    wait(SOURCE_INTRO);
    spawn fire_b();
    loop {
        card_wait(-64fx, 160);
        card_move_rand(-64fx);
        card_wait(-64fx, 160);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(64fx, 128fx, 2300, 0, 0, 0, boss_main);
    _ = spawn_enemy(-64fx, 128fx, 2300, 0, 0, 0, boss_b_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
